<?php  use App\Models\ProfilPegawai; use App\Models\User;  test('profil pegawai belongs to a user', function () {     $user = User::factory()->create();     $pegawai = ProfilPegawai::create([         'user_id' => $user->id,         'nama' => 'Test Pegawai',         'jabatan' => 'Pengasuh',     ]);      expect($pegawai->user)->toBeInstanceOf(User::class)         ->and($pegawai->user->id)->toBe($user->id); });  test('profil pegawai casts tanggal lahir to date instance', function () {     $pegawai = ProfilPegawai::create([         'nama' => 'Tanggal Test',         'tanggal_lahir' => '1995-10-25',     ]);      expect($pegawai->tanggal_lahir)->toBeInstanceOf(\Illuminate\Support\Carbon::class)         ->and($pegawai->tanggal_lahir->format('Y-m-d'))->toBe('1995-10-25'); });